"""Scoped manuscript migration for the author's response-by-response review.

Preserves unrelated paragraphs and references; refuses concurrent modification.
Run separately from appendix regeneration so later prose edits are not overwritten.
"""
import argparse
import datetime
from pathlib import Path

REPLACEMENTS = {
 '설계 원리와 현장 검토 결과의 연결은 표 4-12와 같다.': '설계 원리와 현장 검토 결과의 연결은 표 4-12와 같다. 척도 문항은 기능에 대한 반응을, 선택형 보완 요구와 자유응답은 구체적인 수정 요구와 수업 적용 조건을 보여준다.',
 '자유응답은 문항별로 원문과 응답자 번호를 보존하고,': '자유응답은 문항별로 원문과 응답자 번호를 보존하고, 한 응답의 서로 다른 요구·우려·긍정 평가를 의미 단위로 구분하였다. 각 의미 단위를 연구 목적의 배경, 적용 조건과 한계, 설계상 딜레마, 긍정 평가, 구체적인 보완 요구, 탐구 수행 답변으로 해석한 뒤 필요한 조치를 묶었다. 기존 서비스 문항 6과 EASWA 문항 20·22·23은 평가 대상을 구분하였으며, 문항 6에 작성된 구체적인 EASWA 화면 의견은 보충 근거로 사용하였다. 문항 20-1의 원인 설명은 탐구 수행 자료로 별도 판정하였다. 일반적인 난이도·차시 우려를 모두 즉시 개선 요구로 바꾸지 않았고, 한 명이 지적한 구체적인 수정 요구도 검토에 포함하였다. 표 4-13의 범주별 언급 수는 내용의 분포이며 수정 우선순위나 채택한 개선 수를 뜻하지 않는다.',
 '이 절에서는 현장 전문가 검토에서 도출한 요구와 실제 보완 내역을 연결한다.': '이 절에서는 현장 전문가 검토에서 도출한 요구와 실제 보완 내역을 연결한다. 응답별 검토를 바탕으로 용어·영어와 그래프 기본 표기, 눈에 띄게 어색한 안내 문장, 단계 안내와 이해 점검 질문을 시연 전 우선 보완 후보로 정하였다. 선수 지식·내용 난이도와 차시 우려는 적용 조건 및 한계로 논의하고, 쉬운 활동 구성과 교사 지원 자료 등은 향후 과제로 구분하였다. 척도 응답이 높거나 언급 인원이 적다는 이유만으로 구체적인 문제를 제외하지 않되, 모든 우려를 새로운 기능 요구로 바꾸지는 않았다. 표 4-14에는 실제 보완한 내용과 확인이 남은 범위를 구분하며, 예비교사 조사 전에 제공한 기능·자료와 조사에 사용할 배포본을 기록한다.',
 '이 해석은 보완의 방향도 함께 제한한다.': '이 해석은 안내와 학습자의 독립적 수행 사이의 딜레마로 이어진다. 본 연구가 줄이려는 부담은 코딩, 자료 검색·다운로드, 실행 환경 설정과 같은 기술 실행 부담이며, 천문 개념과 자료를 해석하는 지적 과제까지 없애려는 것은 아니다. Q20/R11은 현재 키워드가 없으면 차이 원인을 설명하기 어려울 수 있다고 보았다. 이는 제공된 단서가 해석을 돕는다는 조건부 장점으로 읽을 수 있는 동시에, 단서 없이도 독립적으로 설명할 수 있는지는 확인되지 않았다는 뜻이다. Q22/R09의 교사 설명과 버튼 조작에 그칠 수 있다는 우려도 함께 고려해야 한다. 따라서 용어·축·단계의 뜻과 다음 행동은 이해할 수 있게 안내하되, 원인과 결론을 학습자 대신 확정하지 않는 설명 범위를 검토할 필요가 있다. 어떤 안내가 어느 수준의 학습자에게 필요한지는 이번 교사 검토만으로 결정할 수 없으며, 실제 학생의 수행과 설명을 살피는 후속 적용이 필요하다. 우선 보완과 장기적인 설명 지원 과제를 구분한 이유도 여기에 있다(4.6; 표 4-17).',
 '1차 조사에서 현재 형태의 활용 의향은 평균 3.92였고,': '1차 조사에서 현재 형태의 활용 의향은 평균 3.92였고, 동아리·과제연구는 수업 형태의 단일 최빈 선택지인 5명이었다. 차시를 선택한 응답은 합계 7명이어서 정규 수업보다 동아리 활용을 선호한다고 결론 내리기는 어렵다. 자유응답에는 심화 선택자 중심의 적용 예상(Q22/R08), 천문 진로 희망 학생 대상의 별도 활동 의향(Q22/R09), 개념 설명부터 탐구까지 3차시 이상 필요하다는 예상(Q22/R10)이 있었다. 이는 대상 수준·선수 개념·교사 준비에 따라 활용 가능성이 달라질 수 있음을 보여준다. 3차시는 교사의 예상이며 실제 학교 수업에서 측정한 시간이 아니다. 활동의 교육과정상 주제 연결과 과제 난이도·차시 적합성을 구분하여 적용 범위를 정할 필요가 있다.',
 '현장 전문가 검토 참여자와 예정된 예비교사 조사 참여자가 모두 현직 교사와 예비교사로 구성되어,': '현장 전문가 검토 참여자와 예정된 예비교사 조사 참여자가 모두 교사와 예비교사로 구성되어, 최종 사용자인 중·고등학생의 용어 이해와 활동 난이도를 직접 확인하지 못하였다. 비전공 교사의 직접적인 어려움(Q20/R01)과 학생의 선수 지식·수준에 관한 우려(Q20/R05·R09, Q22/R06·R08)는 식현상 모듈의 적용 수준을 제한하는 근거다. 그러나 일반 고등학생에게 실제로 얼마나 어려웠는지를 측정한 결과는 아니다. 특히 용어의 구두 설명을 충분히 제공하지 않았다는 진행자의 회고가 있어, 개념 설명을 포함한 실제 수업과 이번 시연의 운영 조건을 구분해야 한다. 내용이 성취기준의 주제와 연결된다는 사실만으로 수행 과제의 수준과 분량까지 적합하다고 판단할 수는 없다. 후속 연구에서는 학생 대상 검토를 통해 일반 수업과 심화 선택·동아리 활동의 적합성을 구체화할 필요가 있다. 또한 동시 접속 처리 용량과 장기 운영 비용은 별도 운영 과제다. 교사연수 규모의 처리 결과(4.7.2)와 다수 학급의 동시 사용 조건을 구분하고, 후속 시연에서 발생한 지연·실패를 기록하여 보완 우선순위를 조정해야 한다.',
 '자유응답과 탐구 수행 산출물의 부호화는 연구자 1인이 수행하였다.': "자유응답과 탐구 수행 산출물의 최종 해석은 연구자 1인이 담당하므로, 범주 설정과 응답 귀속에 연구자 관점이 개입할 수 있다. 원문·문항 맥락·의미 단위별 판정과 연구자의 검토 의견을 연결하여 다시 확인할 수 있도록 하였으며, 2차 조사에서는 이 범주를 초기 부호로 사용한다(3.6). 이러한 검토 기록은 복수의 독립 부호화자에 의한 신뢰도 확인을 대신하지 못한다. 부호화자 간 신뢰도의 적용 여부는 연구의 성격에 따라 판단할 수 있다는 논의(O'Connor & Joffe, 2020)에 비추어, 본 연구의 자유응답 분석은 응답 경향과 보완 요구를 파악하기 위한 형성적 자료로 해석한다. 범주별 수치는 해당 내용을 언급한 고유 응답자 수이며, 한 응답자가 둘 이상의 범주에 해당할 수 있다. 긍정 평가·적용 조건·수행 설명과 수정 요구를 구분한 응답별 판단은 부록 A에 제시하였다.",
 '첫째, EASWA의 설계 원리와 공용 워크플로를 다양한 천문탐구 주제로 확장할 필요가 있다.': '첫째, 탐구 주제를 확장하는 것과 함께 학습자의 수준에 맞게 활동 난이도를 구성할 필요가 있다. 식현상 모듈의 선수 개념과 심화 수준에 관한 교사 의견을 고려하면, 모든 활동을 같은 난이도로 제공하기보다 쉬운 자료 읽기에서 시작해 조건 조절과 원인 설명으로 이어지는 구성이 필요하다. 기존 성단 색등급도 모듈을 표 자료와 교과서에서 다루는 전향점 맞추기 중심의 활동으로 단순화하는 방안을 검토할 수 있다. 연주시차와 달의 위상 등 기초 주제로의 확장도 후속 개발 후보이다. 이러한 제안은 쉬운 모듈의 개발·적용이 완료되었다는 뜻이 아니며, 실제 학생의 수행을 통해 적절성을 확인해야 한다.',
 '넷째, EASWA의 사용성과 접근성을 지속적으로 개선할 필요가 있다.': '넷째, 용어·그래프 기본 표기의 이해, 안내 문장의 자연스러움, 단계별 행동과 이해 점검 질문의 발견성을 우선 점검하고 이후 업데이트에서도 지속적으로 개선할 필요가 있다. 기존 번역 기능의 지원 범위와 별도의 개념 설명이 필요한 부분을 구분하며, 질문을 추가하는 것만으로 수행자의 이해가 확인된다고 보지 않아야 한다. 상세 개념 설명을 위한 대화형 지원도 후속 개발에서 검토할 수 있으나, LLM·MCP 등을 연결하는 구현 아이디어와 설명의 정확성·독립적 해석·교사 지원 효과의 검증은 구분해야 한다. 학교 기기와 브라우저 환경, 동시 사용 규모별 대기와 실패도 실제 운영 기록을 바탕으로 점검할 필요가 있다.',
}

def main():
    p=argparse.ArgumentParser();p.add_argument('--paper',type=Path,required=True);args=p.parse_args()
    original=args.paper.read_bytes();text=original.decode('utf-8').replace('\r\n','\n')
    refs=text.split('# 참고문헌',1)[1].split('<!-- EASWA_RESPONSE_REVIEW_START -->',1)[0]
    lines=text.splitlines();changed=[]
    for prefix,new in REPLACEMENTS.items():
        indices=[i for i,line in enumerate(lines) if line.startswith(prefix)]
        if new in lines: continue
        assert len(indices)==1,(prefix,indices)
        lines[indices[0]]=new;changed.append(prefix)
    text='\n'.join(lines)+'\n'
    # Integrate positive evidence into the existing fourth conclusion, not a new section.
    old='정보 제시 기능은 긍정적으로 평가되었고, 별도로 용어·개념 설명, 그래프 읽기, 비교·기록 활동, 교사 지원 자료에 대한 보완 요구가 확인되었다. 개선은 각 응답의 구체적인 내용과 관련 설계 원리를 연결하여 도출하였다.'
    new='자유응답에서도 직접 천문학자의 과정을 수행한다는 점(Q22/R04), 코딩·자료 수집 없이 실제 자료를 다룬다는 점(Q22/R12), 시각 자료와 실제 데이터의 활용(Q23/R05), 직접 조작과 신뢰할 수 있다고 느낀 자료원(Q23/R10)이 긍정적으로 평가되었다. 이는 설계 취지에 대한 참여자의 반응이며 실제 학생의 학습 효과나 자료 정확성의 독립 검증은 아니다. 동시에 용어·기본 표기, 문장의 자연스러움, 단계 안내·이해 점검은 우선 보완 후보로, 선수 지식·차시·교사 준비는 적용 조건과 후속 과제로 구분하였다.'
    if old in text: text=text.replace(old,new,1);changed.append('6.1 positive evidence and differentiated follow-ups')
    assert new in text
    assert text.split('# 참고문헌',1)[1].split('<!-- EASWA_RESPONSE_REVIEW_START -->',1)[0]==refs
    assert args.paper.read_bytes()==original,'Concurrent edit; retry on current manuscript'
    backup=args.paper.parent/'원고_백업'/f'{args.paper.stem}_연구자검토본문반영전_{datetime.datetime.now():%Y%m%d_%H%M%S}.md'
    backup.write_bytes(original);args.paper.write_text(text,encoding='utf-8')
    print({'paragraphs_changed':len(changed),'backup':str(backup)})

if __name__=='__main__':main()
